    schema: [],
  },
  create: (context) => ({
    root(node) {
      const plan = readPlan(node as unknown as MarkdownNode);
      const table = plan.tables.get("risks");
      if (!plan.tables.has("cases")) return;
      if (!table) {
        context.report({
          loc: plan.tables.get("cases")!.node.position!,
          messageId: "noTable",
        });
