const PAGE_MATCHERS = new Set([
  "toBeVisible",
  "toBeHidden",
  "toBeEnabled",
  "toBeDisabled",
  "toBeChecked",
  "toBeEditable",
  "toBeEmpty",
  "toBeFocused",
  "toBeAttached",
  "toBeInViewport",
  "toHaveText",
  "toContainText",
  "toHaveValue",
  "toHaveValues",
  "toHaveCount",
  "toHaveAttribute",
  "toHaveClass",
  "toHaveCSS",
  "toHaveId",
  "toHaveJSProperty",
  "toHaveScreenshot",
  "toHaveAccessibleName",
  "toHaveAccessibleDescription",
  "toHaveAccessibleErrorMessage",
  "toHaveRole",
  "toMatchAriaSnapshot",
]);

